package main

import (
	"fmt"
	"unsafe"
)

func main() {
	var f float32 = 1.5
	// Reinterpret the float's bits as a uint32 via unsafe.Pointer:
	bits := *(*uint32)(unsafe.Pointer(&f))
	fmt.Printf("%#x\n", bits) // 0x3fc00000 (IEEE-754 repr)
}

package main

import (
	"fmt"
	"unsafe"
)

func main() {
	a := [3]int32{10, 20, 30}
	p := unsafe.Pointer(&a[0])
	// Step to a[2] with single-expression arithmetic (never store the uintptr):
	third := (*int32)(unsafe.Pointer(uintptr(p) + 2*unsafe.Sizeof(a[0])))
	fmt.Println(*third) // 30
}

