type S struct{ A, B int64 }

func main() {
	s := &S{A: 1, B: 42}
	// WRONG: uintptr stored across statements — GC may invalidate it.
	//   u := uintptr(unsafe.Pointer(s)); p := unsafe.Pointer(u + off)
	// RIGHT: one expression, no surviving uintptr:
	bp := unsafe.Pointer(uintptr(unsafe.Pointer(s)) + unsafe.Offsetof(s.B))
	fmt.Println(*(*int64)(bp)) // 42
}

