package main

import (
	"fmt"
	"unsafe"
)

// bytesToString shares b's backing array — no copy.
// Caller MUST NOT mutate or free b while the result is in use.
func bytesToString(b []byte) string {
	if len(b) == 0 {
		return ""
	}
	return unsafe.String(&b[0], len(b)) // Go 1.20+
}

func main() {
	b := []byte("hello")
	fmt.Println(bytesToString(b)) // hello
}

