solution.code:
package solution

import "unsafe"

// StringToBytes shares s's backing array. The result MUST NOT be mutated:
// strings are immutable and the compiler may place them in read-only memory.
func StringToBytes(s string) []byte {
	if len(s) == 0 {
		return nil
	}
	// unsafe.StringData gives the *byte at the start of s (Go 1.20+).
	return unsafe.Slice(unsafe.StringData(s), len(s))
}

// BytesToString shares b's backing array. b MUST NOT be mutated or freed
// while the returned string is in use.
func BytesToString(b []byte) string {
	if len(b) == 0 {
		return ""
	}
	return unsafe.String(&b[0], len(b))
}

codeLab.testHarness:
package solution

import (
	"testing"
	"unsafe"
)

func TestBytesToString(t *testing.T) {
	b := []byte("hello")
	s := BytesToString(b)
	if s != "hello" {
		t.Fatalf("got %q want hello", s)
	}
	// Same backing pointer => no copy happened.
	if unsafe.StringData(s) != &b[0] {
		t.Errorf("BytesToString copied; want shared backing array")
	}
}

func TestStringToBytes(t *testing.T) {
	s := "world"
	b := StringToBytes(s)
	if string(b) != "world" {
		t.Fatalf("got %q want world", b)
	}
	if &b[0] != unsafe.StringData(s) {
		t.Errorf("StringToBytes copied; want shared backing array")
	}
}

func TestEmpty(t *testing.T) {
	if StringToBytes("") != nil {
		t.Errorf("empty string should give nil slice")
	}
	if BytesToString(nil) != "" {
		t.Errorf("nil slice should give empty string")
	}
}

