func fieldB(s *S) int64 {
	// pointer -> uintptr -> add -> back to unsafe.Pointer, all at once:
	p := unsafe.Pointer(uintptr(unsafe.Pointer(s)) + unsafe.Offsetof(s.B))
	return *(*int64)(p)
}

func ReadUint32LE(b []byte) uint32 {
	if len(b) < 4 {
		panic("need at least 4 bytes")
	}
	// Reinterpret the first 4 bytes as a uint32.
	// NOTE: correct ONLY on little-endian hardware. Prefer
	// encoding/binary.LittleEndian.Uint32 for portability.
	return *(*uint32)(unsafe.Pointer(&b[0]))
}

package main

import (
	"fmt"
	"unsafe"
)

type S struct {
	A int32
	B int64
}

// FieldByOffset returns a *T pointing at the field `off` bytes into *s.
// The conversion pointer -> add -> pointer happens in one expression,
// so no uintptr survives a statement boundary (GC-safe).
func FieldByOffset[T any](s *S, off uintptr) *T {
	return (*T)(unsafe.Add(unsafe.Pointer(s), off))
}

func main() {
	s := &S{A: 1, B: 42}
	// Offsetof is a compile-time constant; passing it inline keeps
	// the whole address computation a single expression.
	bp := FieldByOffset[int64](s, unsafe.Offsetof(s.B))
	fmt.Println(*bp) // 42
	*bp = 100        // the returned pointer is a real, GC-tracked *T
	fmt.Println(s.B) // 100
}

